+package job
+
+import (
+	"crypto/sha256"
+	"encoding/hex"
+	"fmt"
+	"log"
+	"strings"
+	"sync"
+	"time"
+)
+
+type Manager struct {
+	mu   sync.RWMutex
+	jobs map[string]*Job
+}
+
+func NewManager() *Manager {
+	return &Manager{
+		jobs: make(map[string]*Job),
+	}
+}
+
+func (m *Manager) Get(id string) (*Job, bool) {
+	m.mu.RLock()
+	defer m.mu.RUnlock()
+	job, ok := m.jobs[id]
+	if !ok {
+		return nil, false
+	}
+	return job, true
+}
+
+func (m *Manager) generateID(owner, command string, args []string) string {
+	now := time.Now()
+	seed := fmt.Sprintf("%s %d.%d %s %s", owner, now.Unix(), now.Nanosecond(), command, strings.Join(args, " "))
+	hash := sha256.Sum256([]byte(seed))
+	shortHash := hex.EncodeToString(hash[:])[:6]
+	if _, exists := m.Get(shortHash); exists {
+		return m.generateID(owner, command, args)
+	}
+	return shortHash

